733: func nativeHarnessBrokerPublicEnvironment(proofRoot string, environment map[string]string) (map[string]string, error) {
734: 	if len(environment) != 4 {
735: 		return nil, fmt.Errorf("synthetic native broker public environment must contain exactly four keys")
736: 	}
737: 	resolve := func(name, path string) (string, error) {
738: 		if strings.TrimSpace(path) == "" || !filepath.IsAbs(path) {
739: 			return "", fmt.Errorf("synthetic native broker %s must be an absolute directory", name)
740: 		}
741: 		info, err := os.Stat(path)
742: 		if err != nil || !info.IsDir() {
743: 			return "", fmt.Errorf("synthetic native broker %s directory unavailable", name)
744: 		}
745: 		resolved, err := filepath.EvalSymlinks(path)
746: 		if err != nil || !filepath.IsAbs(resolved) {
747: 			return "", fmt.Errorf("synthetic native broker %s physical directory unavailable", name)
748: 		}
749: 		return filepath.Clean(resolved), nil
750: 	}
751: 	root, err := resolve("proof root", proofRoot)
752: 	if err != nil {
753: 		return nil, err
754: 	}
755: 	physical := make(map[string]string, 4)
756: 	for _, name := range []string{"SystemRoot", "WINDIR", "TEMP", "TMP"} {
757: 		path, ok := environment[name]
758: 		if !ok {
759: 			return nil, fmt.Errorf("synthetic native broker public environment key unavailable")
760: 		}
761: 		physical[name], err = resolve(name, path)
762: 		if err != nil {
763: 			return nil, err
764: 		}
765: 	}
766: 	for _, name := range []string{"SystemRoot", "WINDIR"} {
767: 		if nativeHarnessTempWithin(root, physical[name]) || nativeHarnessTempWithin(physical[name], root) {
768: 			return nil, fmt.Errorf("synthetic native broker proof root overlaps a system directory")
769: 		}
770: 	}
771: 	for _, name := range []string{"TEMP", "TMP"} {
772: 		if !nativeHarnessTempWithin(proofRoot, environment[name]) || !nativeHarnessTempWithin(root, physical[name]) {
773: 			return nil, fmt.Errorf("synthetic native broker %s escapes the isolated proof root", name)
774: 		}
775: 	}
776: 	return map[string]string{
777: 		"SystemRoot": environment["SystemRoot"], "WINDIR": environment["WINDIR"],
778: 		"TEMP": environment["TEMP"], "TMP": environment["TMP"],
779: 	}, nil
780: }
