782: // Windows comparisons apply to the original and EvalSymlinks-resolved paths.
783: func nativeHarnessTempWithin(root, path string) bool {
784: 	relative, err := filepath.Rel(strings.ToLower(filepath.Clean(root)), strings.ToLower(filepath.Clean(path)))
785: 	return err == nil && relative != ".." && !strings.HasPrefix(relative, ".."+string(filepath.Separator)) && !filepath.IsAbs(relative)
